// Typed access to the SRD data generated by scripts/build-data.mjs.
// Source: System Reference Document 5.1 by Wizards of the Coast, CC-BY-4.0.
//
// This module holds the small data every page needs (classes, races, equipment...).
// The big lists (spells, monsters, magic items) live in ./library so they only download
// on pages that use them. Don't import ./library from code that loads on every page.
import equipmentJson from './equipment.json';
import conditionsJson from './conditions.json';
import racesJson from './races.json';
import classesJson from './classes.json';
import skillsJson from './skills.json';
import backgroundsJson from './backgrounds.json';

export type Ability = 'str' | 'dex' | 'con' | 'int' | 'wis' | 'cha';
export const ABILITIES: Ability[] = ['str', 'dex', 'con', 'int', 'wis', 'cha'];
export const ABILITY_NAMES: Record<Ability, string> = {
  str: 'Strength',
  dex: 'Dexterity',
  con: 'Constitution',
  int: 'Intelligence',
  wis: 'Wisdom',
  cha: 'Charisma',
};

export interface Spell {
  id: string;
  name: string;
  level: number;
  school: string;
  castingTime: string;
  range: string;
  components: string;
  duration: string;
  concentration: boolean;
  ritual: boolean;
  classes: string[];
  desc: string;
  higherLevel: string;
  homebrew?: boolean;
}

export interface NamedBlock {
  name: string;
  desc: string;
}

export interface Monster {
  id: string;
  name: string;
  size: string;
  type: string;
  subtype: string;
  alignment: string;
  ac: number;
  acType: string;
  hp: number;
  hitDice: string;
  speed: string;
  abilities: number[];
  saves: string[];
  skills: string[];
  vulnerabilities: string[];
  resistances: string[];
  immunities: string[];
  conditionImmunities: string[];
  senses: string;
  languages: string;
  cr: number;
  crLabel: string;
  xp: number;
  traits: NamedBlock[];
  actions: NamedBlock[];
  reactions: NamedBlock[];
  legendary: NamedBlock[];
  homebrew?: boolean;
}

export interface MagicItem {
  id: string;
  name: string;
  category: string;
  rarity: string;
  attunement: boolean;
  subtitle: string;
  desc: string;
  homebrew?: boolean;
}

export interface Equipment {
  id: string;
  name: string;
  category: string;
  subcategory: string;
  cost: string;
  weight: number | null;
  detail: string;
  properties: string[];
  weapon: {
    category: string;
    range: string;
    dice: string;
    type: string;
    versatile: string | null;
    finesse: boolean;
  } | null;
  armor: { base: number; dex: boolean; maxDex: number | null; category: string } | null;
  desc: string;
}

export interface Condition {
  id: string;
  name: string;
  desc: string;
}

export interface Subrace {
  id: string;
  name: string;
  desc: string;
  abilityBonuses: Partial<Record<Ability, number>>;
  traits: NamedBlock[];
}

export interface Race {
  id: string;
  name: string;
  speed: number;
  size: string;
  abilityBonuses: Partial<Record<Ability, number>>;
  desc: string;
  languages: string;
  traits: NamedBlock[];
  subraces: Subrace[];
}

export interface Feature extends NamedBlock {
  level: number;
}

export interface ClassLevel {
  level: number;
  profBonus: number;
  features: string[];
  slots: number[] | null;
  cantrips: number | null;
}

export interface DndClass {
  id: string;
  name: string;
  hitDie: number;
  savingThrows: Ability[];
  proficiencies: string[];
  skillChoices: { choose: number; from: string[] };
  spellcastingAbility: Ability | null;
  levels: ClassLevel[];
  features: Feature[];
  subclasses: Subclass[];
}

export interface Subclass {
  name: string;
  flavor: string;
  desc: string;
  features: Feature[];
}

/** A user-made subclass. SRD subclasses live inside their DndClass instead. */
export interface HomebrewSubclass extends Subclass {
  id: string;
  classId: string;
  homebrew: true;
}

export interface Skill {
  id: string;
  name: string;
  ability: Ability;
  desc: string;
}

export interface Background {
  id: string;
  name: string;
  skills: string[];
  feature: NamedBlock | null;
}

export const equipment = equipmentJson as Equipment[];
export const conditions = conditionsJson as Condition[];
export const races = racesJson as Race[];
export const classes = classesJson as DndClass[];
export const skills = skillsJson as Skill[];
export const backgrounds = backgroundsJson as Background[];

export const byId = <T extends { id: string }>(arr: T[]) => new Map(arr.map((x) => [x.id, x]));
export const equipmentById = byId(equipment);
export const raceById = byId(races);
export const classById = byId(classes);
export const skillById = byId(skills);
